#!/bin/bash
# test_analyze_sketch_v5.sh
# בדיקת קצה-לקצה של analyze-sketch v5 - בלי צורך במסך באפליקציה.
# מריץ N פעמים (ברירת מחדל 3): נרשם כמשתמש אנונימי חדש, מעלה את תמונת
# השרטוט (מוטבעת בקובץ הזה, base64), קורא ל-analyze-sketch, ומדפיס
# את תוצאת כל הרצה + שומר אותה לקובץ JSON נפרד לבדיקה/שליחה לקלוד.
#
# הערה חשובה: הלוגיקה כאן נכתבה לפי תיעוד ה-REST API הרגיל של Supabase
# (auth/v1/signup לרישום אנונימי, storage/v1/object להעלאת קבצים,
# functions/v1/<name> להרצת Edge Function) - אבל לא נבדקה בפועל מול
# ה-API החי (הסביבה שבה נכתב הסקריפט חסומה ל-*.supabase.co). אם שלב
# כלשהו נכשל - הדפס/י לי את פלט השגיאה המדויק (כולל קוד ה-HTTP) ונתקן.

set -uo pipefail

SUPABASE_URL="https://iywhxmuzvincfmezijtv.supabase.co"
ANON_KEY="sb_publishable_Px6BOsQjEiEtsHXULMt6SA_DwlJrW66"
FUNCTION_NAME="analyze-sketch"
RUNS="${1:-3}"

WORKDIR="$(mktemp -d)"
IMG_PATH="$WORKDIR/sketch.jpg"

echo "=== מחלץ את תמונת השרטוט המוטבעת ==="
base64 -d > "$IMG_PATH" << 'IMG_B64_EOF'

IMG_B64_EOF
echo "תמונה חולצה ל-$IMG_PATH ($(wc -c < "$IMG_PATH") בתים)"

for i in $(seq 1 "$RUNS"); do
  echo ""
  echo "================ הרצה $i מתוך $RUNS ================"

  echo "--- שלב 1: הרשמה אנונימית ---"
  AUTH_RESP=$(curl -s -w "\nHTTP_STATUS:%{http_code}" -X POST "$SUPABASE_URL/auth/v1/signup" \
    -H "apikey: $ANON_KEY" \
    -H "Content-Type: application/json" \
    --data '{}')
  AUTH_STATUS=$(echo "$AUTH_RESP" | grep -o 'HTTP_STATUS:[0-9]*' | cut -d: -f2)
  AUTH_BODY=$(echo "$AUTH_RESP" | sed 's/HTTP_STATUS:[0-9]*$//')
  echo "קוד HTTP: $AUTH_STATUS"

  ACCESS_TOKEN=$(echo "$AUTH_BODY" | grep -o '"access_token":"[^"]*"' | head -1 | cut -d'"' -f4)
  USER_ID=$(echo "$AUTH_BODY" | grep -o '"id":"[^"]*"' | head -1 | cut -d'"' -f4)

  if [ -z "$ACCESS_TOKEN" ] || [ -z "$USER_ID" ]; then
    echo "❌ הרשמה אנונימית נכשלה. תגובה מלאה:"
    echo "$AUTH_BODY"
    echo "(חשוד מרכזי: 'Enable anonymous sign-ins' לא מסומן ב-Dashboard -> Authentication -> Sign In / Providers)"
    continue
  fi
  echo "משתמש אנונימי: $USER_ID"

  echo "--- שלב 2: העלאת תמונת השרטוט ---"
  TS=$(date +%s)
  STORAGE_PATH="${USER_ID}/sketch-test-${TS}.jpg"
  UPLOAD_RESP=$(curl -s -w "\nHTTP_STATUS:%{http_code}" -X POST \
    "$SUPABASE_URL/storage/v1/object/renders/${STORAGE_PATH}" \
    -H "apikey: $ANON_KEY" \
    -H "Authorization: Bearer $ACCESS_TOKEN" \
    -H "Content-Type: image/jpeg" \
    --data-binary "@$IMG_PATH")
  UPLOAD_STATUS=$(echo "$UPLOAD_RESP" | grep -o 'HTTP_STATUS:[0-9]*' | cut -d: -f2)
  UPLOAD_BODY=$(echo "$UPLOAD_RESP" | sed 's/HTTP_STATUS:[0-9]*$//')
  echo "קוד HTTP: $UPLOAD_STATUS"
  if [ "$UPLOAD_STATUS" != "200" ]; then
    echo "❌ העלאת התמונה נכשלה. תגובה מלאה:"
    echo "$UPLOAD_BODY"
    continue
  fi
  echo "הועלה ל: $STORAGE_PATH"

  echo "--- שלב 3: קריאה ל-$FUNCTION_NAME ---"
  RESULT=$(curl -s -X POST "$SUPABASE_URL/functions/v1/$FUNCTION_NAME" \
    -H "apikey: $ANON_KEY" \
    -H "Authorization: Bearer $ACCESS_TOKEN" \
    -H "Content-Type: application/json" \
    --data "{\"sketchImagePath\":\"${STORAGE_PATH}\"}")

  OUT_FILE="analyze_test_run_${i}.json"
  echo "$RESULT" > "$OUT_FILE"
  echo "התוצאה המלאה נשמרה ב: $OUT_FILE"
  echo "--- תמצית (חיפוש טקסטואלי - לא תלוי ב-jq/python) ---"
  echo "$RESULT" | grep -o '"analysisId":"[^"]*"'
  echo "$RESULT" | grep -o '"roomType":"[^"]*"'
  echo "$RESULT" | grep -o '"labelHe":"[^"]*"'
  echo "$RESULT" | grep -o '"totalAreaSqm":[0-9.]*'
done

echo ""
echo "================ סיכום ================"
echo "כל תוצאה מלאה נשמרת בתיקייה הנוכחית: analyze_test_run_1.json, analyze_test_run_2.json, ..."
echo "תעלה/י את הקבצים האלה (או תדביק/י את התוכן) חזרה לצ'אט כדי שנבדוק כל 'analysisId' וכל 'roomType' שיצא."
